insert into public.questions
  (id, domain, objective, prompt, options, correct_index, explanation, source_url)
select
  q.id, q.domain, q.objective, q.prompt, q.options, q.correct_index,
  q.explanation, q.source_url
from jsonb_to_recordset($question_bank$
[
  {"id":"cloud-consumption-costs","domain":"cloud","objective":"Describe the consumption-based model and compare cloud pricing models","prompt":"A community radio station expects its online audience to grow, but cannot predict when. Which pricing approach lets it begin with low infrastructure spend and pay for resources as it uses them?","options":["Buy peak-capacity hardware up front","Use consumption-based cloud pricing","Purchase a fixed set of servers for five years","Build a private datacenter before launch"],"correct_index":1,"explanation":"Consumption-based pricing charges for resources as they are used. It can reduce the need for large up-front purchases, while actual costs still depend on usage and service pricing.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-hybrid-model","domain":"cloud","objective":"Define public, private, and hybrid cloud models and identify use cases","prompt":"A health organization runs a sensitive records system in its own datacenter and uses a public cloud for its public website. Which cloud model describes this arrangement?","options":["Public cloud only","Private cloud only","Hybrid cloud","Community cloud"],"correct_index":2,"explanation":"A hybrid cloud combines private infrastructure with public cloud services, allowing an organization to use both environments for different needs.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-shared-responsibility","domain":"cloud","objective":"Describe the shared responsibility model","prompt":"A company uses a cloud-hosted email application and creates employee accounts. Which task remains the company’s responsibility?","options":["Maintaining the physical datacenter","Replacing failed storage hardware","Managing employee access and account settings","Patching the provider’s network switches"],"correct_index":2,"explanation":"The provider manages the underlying service infrastructure, while the customer remains responsible for appropriate use of the service, including user identities and access. Responsibility varies by service type.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-elasticity","domain":"cloud","objective":"Describe the benefits of high availability and scalability in the cloud","prompt":"A ticketing site experiences brief traffic surges when popular events go on sale. Which cloud capability lets it add capacity for the surge and reduce it afterward?","options":["Elasticity","Data sovereignty","Resource locking","Capital expenditure"],"correct_index":0,"explanation":"Elasticity is the ability to increase or reduce resources as demand changes, helping respond to workload variation without permanently keeping peak capacity.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-saas","domain":"cloud","objective":"Describe SaaS and identify appropriate use cases for cloud service types","prompt":"A small nonprofit wants to use a complete collaboration application through a browser. It does not want to deploy or maintain the application. Which service type best fits?","options":["IaaS","PaaS","SaaS","On-premises hosting"],"correct_index":2,"explanation":"Software as a Service provides a ready-to-use application managed by its provider. The customer still manages its users, data, and service configuration.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-serverless","domain":"cloud","objective":"Describe serverless","prompt":"A developer needs a short task to run whenever a new image arrives in storage, without maintaining a server. Which approach is the closest fit?","options":["A serverless event-triggered function","A dedicated physical server","A fixed-size virtual machine that runs continuously","A private network endpoint"],"correct_index":0,"explanation":"Serverless compute can run code in response to events while the cloud provider manages the underlying server infrastructure. Azure Functions is one example.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-public-private-choice","domain":"cloud","objective":"Define public, private, and hybrid cloud models and identify appropriate use cases","prompt":"A government department must keep its cloud environment dedicated to one organization and operate it under its own control. Which cloud model most closely matches that requirement?","options":["Public cloud","Private cloud","Hybrid cloud","SaaS"],"correct_index":1,"explanation":"A private cloud is used by a single organization. It can provide more organizational control, although the organization still manages costs, security, and operations according to its design.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"cloud-paas","domain":"cloud","objective":"Describe IaaS, PaaS, and SaaS and identify appropriate use cases","prompt":"A development team wants to deploy its web application while the provider manages the operating system and runtime. The team still manages its application and data. Which service type is the best match?","options":["IaaS","PaaS","SaaS","Private cloud"],"correct_index":1,"explanation":"Platform as a Service provides a managed application platform. The customer deploys and manages its application and data, while the provider manages more of the underlying stack than in IaaS.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-regions","domain":"architecture","objective":"Describe Azure regions, region pairs, and sovereign regions","prompt":"A company needs to deploy an application close to users in Nairobi to reduce network latency. Which Azure architectural choice should it evaluate first?","options":["Choose an Azure region geographically close to its users","Create a management group","Choose a storage access tier","Add a resource lock"],"correct_index":0,"explanation":"Selecting a suitable region can help reduce latency for users. The organization should also consider service availability, regulatory needs, and resilience requirements when choosing a region.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-zones","domain":"architecture","objective":"Describe availability zones","prompt":"An application must continue operating if a single datacenter location in its Azure region has an outage. Which design should the team consider?","options":["Deploy across availability zones","Put every component in one availability zone","Create a resource group per user","Use a management group as a backup"],"correct_index":0,"explanation":"Availability zones are physically separate locations within an Azure region. Deploying supported components across zones can improve resilience to a zonal outage.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-management-groups","domain":"architecture","objective":"Describe the hierarchy of management groups, subscriptions, and resource groups","prompt":"An organization wants Azure Policy assignments to apply consistently to several subscriptions. Which scope can group subscriptions in a hierarchy?","options":["A subnet","A management group","A storage container","An availability set"],"correct_index":1,"explanation":"Management groups organize subscriptions. Governance settings assigned at a management-group scope can apply to subscriptions beneath it, subject to the configured policy behavior.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-vm-containers","domain":"architecture","objective":"Compare compute types, including containers, virtual machines, and functions","prompt":"A team needs strong control over a guest operating system to run legacy software. Which compute option is the most direct fit?","options":["A virtual machine","A serverless function","A SaaS email service","A storage redundancy option"],"correct_index":0,"explanation":"A virtual machine provides a guest operating system that the customer can configure and manage. That control also means more responsibility than a serverless or SaaS option.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-vnet-subnet","domain":"architecture","objective":"Describe virtual networks and subnets","prompt":"A team wants to place related Azure resources on a logically segmented private network. Which Azure construct provides the network boundary?","options":["Azure Virtual Network","Azure Advisor","Azure Policy","Azure Cost Management"],"correct_index":0,"explanation":"An Azure Virtual Network provides a private networking environment for Azure resources. Subnets divide the address space into smaller network segments.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-expressroute","domain":"architecture","objective":"Describe Azure VPN Gateway and ExpressRoute","prompt":"An organization needs a private, dedicated connection from its office network to Azure through a connectivity provider. Which service should it investigate?","options":["Azure ExpressRoute","Azure DNS","Azure Blob Storage","Azure Functions"],"correct_index":0,"explanation":"ExpressRoute extends an on-premises network to Microsoft cloud services through a connectivity provider using a private connection. The exact design and availability depend on location and provider.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-blob","domain":"architecture","objective":"Compare Azure Storage services","prompt":"A mobile app needs to store user-uploaded photos as unstructured objects. Which Azure storage service is designed for this type of data?","options":["Azure Blob Storage","Azure Virtual Network","Azure Policy","Azure DNS"],"correct_index":0,"explanation":"Azure Blob Storage stores large amounts of unstructured object data, including images, documents, and backups.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-storage-redundancy","domain":"architecture","objective":"Describe Azure Storage redundancy options","prompt":"A workload needs storage data replicated synchronously across availability zones in its primary region. Which redundancy option should the team investigate?","options":["Zone-redundant storage (ZRS)","Locally redundant storage (LRS)","A resource lock","A hot access tier"],"correct_index":0,"explanation":"ZRS replicates data synchronously across availability zones in the primary region. Redundancy choice should reflect availability and recovery requirements, as well as supported services and regions.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-storage-tools","domain":"architecture","objective":"Identify options for moving files, including AzCopy and Azure Storage Explorer","prompt":"An administrator wants a command-line utility purpose-built for copying data to and from Azure Storage. Which tool is the best match?","options":["AzCopy","Azure Advisor","Azure Policy","Azure Service Health"],"correct_index":0,"explanation":"AzCopy is a command-line utility for copying data to or from Azure Storage. Azure Storage Explorer is another option with a graphical interface.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-migration","domain":"architecture","objective":"Describe migration options, including Azure Migrate and Azure Data Box","prompt":"A company needs to assess and plan the migration of its on-premises servers to Azure. Which service is designed to help with discovery and migration planning?","options":["Azure Migrate","Azure DNS","Azure Policy","Microsoft Purview"],"correct_index":0,"explanation":"Azure Migrate helps discover, assess, and plan migration of on-premises workloads to Azure. The right migration path depends on the workload and business requirements.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-entra-mfa","domain":"architecture","objective":"Describe Microsoft Entra ID and authentication methods, including MFA","prompt":"A sign-in policy asks a user for a password and a separate approval on their phone. What authentication method does this illustrate?","options":["Multifactor authentication","Resource tagging","Data redundancy","Infrastructure as code"],"correct_index":0,"explanation":"Multifactor authentication requires more than one verification method. Combining a password with a separate phone-based check can provide an additional layer of account protection.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"architecture-rbac","domain":"architecture","objective":"Describe Azure role-based access control (RBAC)","prompt":"A contractor needs read-only access to one resource group for a short project. Which approach best follows least privilege?","options":["Assign an appropriate reader role at that resource-group scope","Make the contractor an owner of the subscription","Share an administrator account","Assign a global administrator role"],"correct_index":0,"explanation":"Azure RBAC assigns roles to identities at a scope. Choosing a limited role and the narrowest useful scope follows least-privilege access practices.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-pricing-calculator","domain":"management","objective":"Explore the Azure Pricing calculator and describe factors that affect cost","prompt":"Before deploying a test environment, a developer wants to estimate its monthly Azure cost using expected resource types and usage. Which tool should they use?","options":["Azure Pricing calculator","Azure Service Health","Microsoft Entra ID","Azure DNS"],"correct_index":0,"explanation":"The Azure Pricing calculator estimates costs based on selected services and assumptions about usage. Actual charges depend on configuration, consumption, and current pricing.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-tags","domain":"management","objective":"Describe the purpose of tags","prompt":"A team wants to identify Azure resources that belong to a specific department when reviewing costs. Which feature can add this business context to resources?","options":["Tags","Availability zones","Subnets","Functions"],"correct_index":0,"explanation":"Tags are name-value pairs that can help organize resources and provide metadata, such as department or cost center. They do not automatically enforce a policy by themselves.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-policy","domain":"management","objective":"Describe the purpose of Azure Policy","prompt":"An organization wants newly created resources to include a required environment tag. Which Azure service can audit or enforce this requirement?","options":["Azure Policy","Azure Advisor","Azure Functions","Azure Storage Explorer"],"correct_index":0,"explanation":"Azure Policy helps create and assign rules to audit or enforce organizational standards, including requirements for resource tags.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-locks","domain":"management","objective":"Describe the purpose of resource locks","prompt":"An administrator wants to reduce the chance that a critical resource is accidentally deleted. Which control can block deletion at the resource or containing scope?","options":["A delete lock","A cost-center tag","A region pair","A service health alert"],"correct_index":0,"explanation":"A delete lock helps prevent a resource from being deleted. Locks can be applied at supported scopes and inherited by resources beneath them.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-purview","domain":"management","objective":"Describe the purpose of Microsoft Purview in Azure","prompt":"A data team wants to discover and understand data assets across its organization to support data governance. Which service should it explore?","options":["Microsoft Purview","Azure Virtual Machines","Azure VPN Gateway","Azure Functions"],"correct_index":0,"explanation":"Microsoft Purview provides data governance capabilities that help organizations discover, understand, and govern data across their data estate.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-cloud-shell","domain":"management","objective":"Describe Azure Cloud Shell, Azure CLI, and Azure PowerShell","prompt":"An administrator needs a browser-accessible shell with Azure management tools and an authenticated Azure context. Which option is designed for this?","options":["Azure Cloud Shell","Azure Blob Storage","Azure DNS","Azure Advisor"],"correct_index":0,"explanation":"Azure Cloud Shell is a browser-accessible shell for managing Azure resources. It supports command-line environments such as Azure CLI and Azure PowerShell.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-azure-arc","domain":"management","objective":"Describe the purpose of Azure Arc","prompt":"An organization wants to project and manage servers running in its own datacenter and another cloud through Azure management tools. Which service should it explore?","options":["Azure Arc","Azure DNS","Azure Pricing calculator","Azure Blob Storage"],"correct_index":0,"explanation":"Azure Arc extends Azure management capabilities to resources such as servers running outside Azure, including on-premises and other-cloud environments.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-arm-iac","domain":"management","objective":"Describe infrastructure as code and Azure Resource Manager templates","prompt":"A team wants to deploy the same infrastructure configuration repeatedly from a declarative template. Which concept and Azure capability are most relevant?","options":["Infrastructure as code with Azure Resource Manager templates","Manual changes in each resource blade","Azure Service Health notifications","Storage access tiers"],"correct_index":0,"explanation":"Infrastructure as code describes and deploys infrastructure through files rather than relying only on manual setup. Azure Resource Manager templates are one declarative deployment option.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-advisor","domain":"management","objective":"Describe the purpose of Azure Advisor","prompt":"An administrator wants personalized recommendations that may improve cost, reliability, security, performance, and operational excellence. Which service provides these recommendations?","options":["Azure Advisor","Azure DNS","Azure Files","Azure VPN Gateway"],"correct_index":0,"explanation":"Azure Advisor analyzes Azure deployments and provides recommendations across areas such as cost, reliability, security, performance, and operational excellence.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-service-health","domain":"management","objective":"Describe the purpose of Azure Service Health","prompt":"A company wants personalized information about Azure service incidents or planned maintenance that may affect its resources. Which service should it check?","options":["Azure Service Health","Azure Pricing calculator","Azure Storage Explorer","Azure Policy"],"correct_index":0,"explanation":"Azure Service Health provides information about Azure service issues, planned maintenance, and other events that may affect the services and regions an organization uses.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"},
  {"id":"management-monitor","domain":"management","objective":"Describe Azure Monitor, including Log Analytics, alerts, and Application Insights","prompt":"A team wants to collect telemetry from an application and configure alerts when monitored conditions are met. Which Azure service family should it use?","options":["Azure Monitor","Azure Policy","Microsoft Purview","Azure Resource Manager"],"correct_index":0,"explanation":"Azure Monitor collects and analyzes telemetry from Azure and other environments. Its capabilities include alerts, Log Analytics, and Application Insights for application monitoring.","source_url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/az-900"}
]
$question_bank$::jsonb) as q(
  id text,
  domain text,
  objective text,
  prompt text,
  options jsonb,
  correct_index smallint,
  explanation text,
  source_url text
)
on conflict (id) do update set
  domain = excluded.domain,
  objective = excluded.objective,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_index = excluded.correct_index,
  explanation = excluded.explanation,
  source_url = excluded.source_url,
  outline_version = date '2026-07-20',
  is_published = true;
